import type {
  ApiErrorResponse,
  Bucket,
  CurrentResponse,
  Field,
  SeriesResponse,
  StatsResponse,
  YearsResponse,
} from './types';

/** Thrown for transport errors and for non-2xx answers of the API. */
export class ApiError extends Error {
  constructor(
    message: string,
    readonly status = 0,
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

const API_BASE = new URL('api/', document.baseURI).href;

function requestUrl(endpoint: string, params: Record<string, string> = {}): string {
  const url = new URL(endpoint, API_BASE);
  for (const [key, value] of Object.entries(params)) {
    url.searchParams.set(key, value);
  }
  return url.toString();
}

async function getJson<T>(endpoint: string, params: Record<string, string> = {}): Promise<T> {
  let response: Response;
  try {
    response = await fetch(requestUrl(endpoint, params), {
      headers: { Accept: 'application/json' },
      cache: 'no-store',
      credentials: 'same-origin',
    });
  } catch (error) {
    throw new ApiError(`Netzwerkfehler: ${(error as Error).message}`);
  }

  const text = await response.text();
  let body: unknown = null;
  if (text.length > 0) {
    try {
      body = JSON.parse(text);
    } catch {
      // A PHP fatal error prints HTML; surface a readable message instead.
      throw new ApiError(
        `Ungültige Antwort von ${endpoint} (HTTP ${response.status})`,
        response.status,
      );
    }
  }

  if (!response.ok) {
    const message = (body as ApiErrorResponse | null)?.error ?? `HTTP ${response.status}`;
    throw new ApiError(message, response.status);
  }

  if (body === null) {
    throw new ApiError(`Leere Antwort von ${endpoint}`, response.status);
  }

  return body as T;
}

/** Newest row of the measurements table. */
export function fetchCurrent(): Promise<CurrentResponse> {
  return getJson<CurrentResponse>('current.php');
}

/** min / avg / max per field over the last `hours` hours. */
export function fetchStats(hours: number): Promise<StatsResponse> {
  return getJson<StatsResponse>('stats.php', { hours: String(hours) });
}

export interface SeriesQuery {
  /** Hours back from now. Omitted together with from/to = complete history. */
  hours?: number;
  /** Inclusive window start, "YYYY-MM-DD" or "YYYY-MM-DD HH:MM:SS". */
  from?: string;
  /** Inclusive window end. */
  to?: string;
  fields: readonly Field[];
  bucket: Bucket;
}

/** Aggregated time series for the chart. */
export function fetchSeries(query: SeriesQuery): Promise<SeriesResponse> {
  const params: Record<string, string> = {
    fields: query.fields.join(','),
    bucket: query.bucket,
  };
  if (query.hours !== undefined) params.hours = String(query.hours);
  if (query.from !== undefined) params.from = query.from;
  if (query.to !== undefined) params.to = query.to;
  return getJson<SeriesResponse>('series.php', params);
}

/** Calendar years that actually contain measurements. */
export function fetchYears(): Promise<YearsResponse> {
  return getJson<YearsResponse>('years.php');
}
